from fractions import Fraction

def find_matrix_systematic(r1, r2):
    p1, q1 = r1.numerator, r1.denominator
    p2, q2 = r2.numerator, r2.denominator

    # 11a + 3b = p2
    # 11c + 3d = q2
    # We want ad - bc = +/- 1

    # Possible values for a:
    # 11a \equiv p2 (mod 3)  =>  2a \equiv p2 (mod 3)  =>  a \equiv 2*p2 (mod 3)
    a_start = (2 * p2) % 3
    for a in range(a_start - 3, a_start + 3, 3):
        b = (p2 - 11 * a) // 3
        if (p2 - 11 * a) % 3 == 0:
            # Now we have a, b. We need c, d.
            # 11c + 3d = q2
            # c \equiv 2*q2 (mod 3)
            c_start = (2 * q2) % 3
            for c in range(c_start - 3, c_start + 3, 3):
                d = (q2 - 11 * c) // 3
                if (q2 - 11 * c) % 3 == 0:
                    det = a * d - b * c
                    if det == 1 or det == -1:
                        return (a, b, c, d), det
    return None, None

