from collections import deque

def get_neighbors(r):
    neighbors = []
    r1 = -r
    if r1 != r: neighbors.append(r1)
    r2 = 1 - r
    if r2 != r: neighbors.append(r2)
    if r != 0:
        r3 = 1 / r
        if r3 != r: neighbors.append(r3)
    return neighbors

