import math
from collections import deque

def get_neighbors(r):
    num, den = r
    neighbors = []
    # r ~ -r
    n1, d1 = -num, den
    if n1 != num or d1 != den:
        neighbors.append((n1, d1))
    # r ~ 1-r
    n2, d2 = den - num, den
    if n2 != num or d2 != den:
        neighbors.append((n2, d2))
    # r ~ 1/r
    n3, d3 = den, num
    if n3 != num or d3 != den:
        neighbors.append((n3, d3))

    simplified = []
    for n, d in neighbors:
        common = math.gcd(n, d)
        n //= common
        d //= common
        if d < 0:
            n = -n
            d = -d
        simplified.append((n, d))
    return list(set(simplified))

def solve():
    start_r = (11, 3)
    target_rs = [(7, 3), (11, 4), (2024, 5), (109, 11), (3, 71), (5, 204)]

    distances = {start_r: 0}
    queue = deque([start_r])

    while queue:
        curr = queue.popleft()
        d = distances[curr]
        for neighbor in get_neighbors(curr):
            if neighbor not in distances:
                distances[neighbor] = d + 1
                queue.append(neighbor)

    results = []
    for target in target_rs:
        if target in distances:
            d = distances[target]
            val = 1 if d % 2 == 0 else 0
            results.append(val)
            print(f"Target {target}: dist {d}, f(r)={val}")
        else:
            print(f"Target {target}: NOT REACHABLE")

    print(f"Sum of f(r): {sum(results)}")

solve()
